export function getSalesData(): SalesRecord[] {
  return rawData;
}

export function getUniqueCategories(): string[] {
  return [...new Set(rawData.map(r => r.category))].sort();
}

export function getUniqueRegions(): string[] {
  return [...new Set(rawData.map(r => r.region))].sort();
}

export function getDateRange(): { min: string; max: string } {
  const dates = rawData.map(r => r.orderDate).sort();
  return { min: dates[0], max: dates[dates.length - 1] };
}
